import {equilibriumTasks,equilibriumCorrect,exchangeStep} from './equilibrium-models.js?v=20261023-physicscomplete01';
import {showEquilibrium} from './equilibrium-scenes.js?v=20261023-physicscomplete01';
export function mountEquilibrium(l,p,root,{save,done,feedback}){const kind=l.widget.slice(12),tasks=equilibriumTasks[kind],w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task%tasks.length,t=tasks[i],a=w.answers[t.id]??={};w.answers[t.id]=a;const $=s=>root.querySelector(s);a.steps??=0;let body=`<p><b>${i+1} / ${tasks.length} · ${t.title}</b></p><p>${t.prompt}</p>`;if(kind==='dynamic'&&t.id!=='escape')body+='<button class="secondary" id="exchangeStep">Run five model steps</button><p id="exchangeCount">'+a.steps+' steps run</p>';body+=t.fields.map(([id,label,opts])=>`<label class="field-label" for="eq-${id}">${label}</label><select class="lab-select" id="eq-${id}"><option value="">Choose…</option>${opts.map(([v,s])=>`<option value="${v}">${s}</option>`).join('')}</select>`).join('');root.innerHTML=body+'<button class="secondary" id="checkEQ">Check reasoning</button><button class="secondary" id="nextEQ">Next case →</button><p id="eqProgress">'+w.passed.length+' / '+tasks.length+' correct</p>';const draw=()=>{let state={a:t.id==='approach'?60:20,b:t.id==='approach'?0:40};for(let n=0;n<Math.min(a.steps,100);n++)state=exchangeStep(state.a,state.b);showEquilibrium(kind,t,state);};for(const[id]of t.fields){const el=$('#eq-'+id);el.value=a[id]??'';el.onchange=e=>{a[id]=e.target.value;save();};}draw();if($('#exchangeStep'))$('#exchangeStep').onclick=()=>{a.steps=Math.min(100,a.steps+5);save();draw();$('#exchangeCount').textContent=a.steps+' steps run';};$('#checkEQ').onclick=()=>{if(!equilibriumCorrect(t,a)||(kind==='dynamic'&&t.id!=='escape'&&a.steps<5)){feedback(kind==='dynamic'?'Run the exchange model, then compare forward and reverse rates. Equal rates can keep unequal amounts constant; a closed boundary retains substances.':kind==='shift'?'Counteract the change: replace removed product, favour the endothermic direction on heating, or favour fewer gas molecules on compression.':'Reverse the observation and energy direction without changing energy magnitude. The reversible symbol alone does not establish equilibrium.',true);return;}if(!w.passed.includes(t.id))w.passed.push(t.id);save();$('#eqProgress').textContent=w.passed.length+' / '+tasks.length+' correct';feedback('Correct: the evidence and reversible-system reasoning agree.');if(w.passed.length===tasks.length){p.widgetDone=true;save();done();}};$('#nextEQ').onclick=()=>{w.task=(i+1)%tasks.length;save();feedback('');mountEquilibrium(l,p,root,{save,done,feedback});};}
